{"command":"cat > /tmp/custom_server.py << 'PY'
import http.server, socketserver, sys
from urllib.parse import urlparse, parse_qs

class H(http.server.BaseHTTPRequestHandler):
    def log_message(self, format, *args):
        sys.stderr.write("REQ %s %s headers=%r\n" % (self.command, self.path, dict(self.headers)))
    def do_GET(self):
        self.handle_req()
    def do_POST(self):
        self.handle_req()
    def handle_req(self):
        p=urlparse(self.path)
        path=p.path
        q=parse_qs(p.query)
        def send(code, body, ctype=None, extra={}):
            if isinstance(body,str): body=body.encode()
            self.send_response(code)
            if ctype: self.send_header("Content-type", ctype)
            for k,v in extra.items(): self.send_header(k,v)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        if path=="/html-1251":
            body="<html><head><title>Rus</title></head><body>Privet</body></html>".encode('windows-1251')
            # actually include cyrillic bytes
            body=b"<html><head><title>\xcf\xf0\xe8\xe2\xe5\xf2</title></head><body>\xcf\xf0\xe8\xe2\xe5\xf2</body></html>"
            send(200, body, "text/html; charset=windows-1251")
        elif path=="/html-header-utf8-meta-1251":
            body=b"<html><head><meta charset='windows-1251'><title>\xcf\xf0</title></head><body>\xcf\xf0</body></html>"
            send(200, body, "text/html; charset=utf-8")
        elif path=="/html-nocharset-header":
            body=b"<html><body>\xcf\xf0</body></html>"
            send(200, body, "text/html")
        elif path=="/html-badtype":
            send(200, b"<html><body>badtype</body></html>", "text/plain")
        elif path=="/html-notype":
            # no content type
            body=b"<html><body>notype</body></html>"
            self.send_response(200); self.send_header("Content-Length", str(len(body))); self.end_headers(); self.wfile.write(body)
        elif path=="/redirect":
            self.send_response(302); self.send_header("Location","/target.html"); self.send_header("Content-Length","0"); self.end_headers()
        elif path=="/redirect-abs":
            self.send_response(301); self.send_header("Location","http://127.0.0.1:8766/target.html"); self.send_header("Content-Length","0"); self.end_headers()
        elif path=="/redirect-rel":
            self.send_response(303); self.send_header("Location","target2.html"); self.send_header("Content-Length","0"); self.end_headers()
        elif path=="/redirect-loop":
            self.send_response(302); self.send_header("Location","/redirect-loop"); self.send_header("Content-Length","0"); self.end_headers()
        elif path=="/target.html":
            send(200, b"<html><head><title>Target</title></head><body>target <img src='pic2.png'></body></html>", "text/html")
        elif path=="/target2.html":
            send(200, b"<html><body>target2</body></html>", "text/html")
        elif path=="/pic2.png":
            import base64
            send(200, base64.b64decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8Xw8AAwMCAO+ip1sAAAAASUVORK5CYII="), "image/png")
        elif path=="/status404":
            send(404, b"<html><body>notfound page</body></html>", "text/html")
        elif path=="/status500":
            send(500, b"server error", "text/plain")
        elif path=="/status201":
            send(201, b"<html><body>created</body></html>", "text/html")
        elif path=="/status204":
            send(204, b"", None)
        elif path=="/echo-headers":
            heads="|".join(f"{k}={v}" for k,v in self.headers.items())
            send(200, f"<html><body>{heads}</body></html>", "text/html")
        elif path=="/asset-headers":
            heads="|".join(f"{k}={v}" for k,v in self.headers.items())
            send(200, heads, "text/plain")
        elif path=="/set-cookie":
            send(200, b"<html><body>cookie set <img src='/pic2.png'></body></html>", "text/html", {"Set-Cookie":"session=abc; Path=/"})
        elif path=="/gzip":
            import gzip
            body=gzip.compress(b"<html><body>gzipped</body></html>")
            send(200, body, "text/html", {"Content-Encoding":"gzip"})
        elif path=="/deflate":
            import zlib
            body=zlib.compress(b"<html><body>deflated</body></html>")
            send(200, body, "text/html", {"Content-Encoding":"deflate"})
        elif path=="/brotli":
            send(200, b"not brotli", "text/html", {"Content-Encoding":"br"})
        elif path=="/slow":
            import time; time.sleep(2); send(200, b"<html><body>slow</body></html>", "text/html")
        elif path=="/asset.css":
            send(200, b"body { background: url(pic2.png); }", q.get("ct",["text/css"])[0])
        elif path=="/asset.js":
            send(200, b"console.log('asset');", q.get("ct",["text/javascript"])[0])
        elif path=="/asset-custom":
            ct=q.get("ct",[None])[0]
            body=q.get("body",["hello"])[0].encode()
            send(200, body, ct)
        elif path=="/auth":
            send(200, f"<html><body>auth={self.headers.get('Authorization')}</body></html>", "text/html")
        elif path.startswith("/redir-asset"):
            self.send_response(302); self.send_header("Location","/pic2.png"); self.send_header("Content-Length","0"); self.end_headers()
        else:
            send(404, b"custom 404", "text/plain")

socketserver.ThreadingTCPServer.allow_reuse_address=True
srv=socketserver.ThreadingTCPServer(("127.0.0.1",8766), H)
print("serving 8766", flush=True)
srv.serve_forever()
PY
python3 /tmp/custom_server.py > /tmp/custom_server.log 2>&1 &
echo $! > /tmp/custom_server.pid
sleep 1
curl -s http://127.0.0.1:8766/target.html; echo
curl -s -i http://127.0.0.1:8766/redirect | head
"}

