def eprint_raw(s):
    # without newline
    if QUIET:
        return
    try:
        sys.stderr.buffer.write(s.encode('utf-8', 'surrogateescape'))
        sys.stderr.buffer.flush()
    except Exception:
        pass

def panic(location, message):
    # emulate Rust panic output (without backtrace unless requested)
    pid = os.getpid()
    out = f"\nthread 'main' ({pid}) panicked at {location}:\n{message}\n"
    bt = os.environ.get("RUST_BACKTRACE", "")
    if bt and bt != "0":
        out += "stack backtrace:\n"
        if bt == "1":
            out += "note: Some details are omitted, run with `RUST_BACKTRACE=full` for a verbose backtrace.\n"
    else:
        out += "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n"
    try:
        sys.stderr.buffer.write(out.encode('utf-8', 'surrogateescape'))
        sys.stderr.buffer.flush()
    except Exception:
        pass
    sys.exit(101)

def rust_os_error(e):
    # e is OSError
    code = e.errno if e.errno is not None else 1
    kind_map = {1:"PermissionDenied",2:"NotFound",5:"PermissionDenied",13:"PermissionDenied",17:"AlreadyExists",20:"NotADirectory",21:"IsADirectory",22:"InvalidInput",24:"Uncategorized",28:"StorageFull",32:"BrokenPipe",98:"AddrInUse",110:"TimedOut",111:"ConnectionRefused"}
    kind = kind_map.get(code, "Uncategorized")
    msg = e.strerror or str(e)
    return f'Os {{ code: {code}, kind: {kind}, message: "{msg}" }}'

