def parse_html(text):
    builder=DomBuilder()
    # normalize CR / CRLF to LF (HTML input preprocessing)
    text=text.replace('\r\n','\n').replace('\r','\n')
    builder.feed(text)
    builder.close()
    return builder.finish()

